package org.sleepwell.app;
import java.time.*;import java.time.temporal.*;import java.util.*;import org.json.*;
/** Optional local-calendar recurrence. Missing metadata retains all original weekly/one-shot semantics. */
final class AlarmRepeat {
 enum Mode{WEEKLY,ODD,EVEN,INTERVAL}
 static final AlarmRepeat WEEKLY=new AlarmRepeat(Mode.WEEKLY,0,null);
 static final Set<Integer> ALL=Set.of(1,2,3,4,5,6,7);
 final Mode mode;final int every;final LocalDate anchor;
 AlarmRepeat(Mode mode,int every,LocalDate anchor){if(mode==null||mode==Mode.INTERVAL&&(every<1||every>365||anchor==null||anchor.getYear()<1970||anchor.getYear()>9998)||mode!=Mode.INTERVAL&&(every!=0||anchor!=null))throw new IllegalArgumentException("Choose a repeat interval of 1–365 days and an anchor date.");this.mode=mode;this.every=every;this.anchor=anchor;}
 boolean custom(){return mode!=Mode.WEEKLY;}
 void check(Alarm alarm){if(!custom())return;if(alarm.nap!=null||alarm.napInvalid||alarm.date!=null||alarm.dateInvalid)throw new IllegalArgumentException("Clear the one-time Run on date before using a custom repeat rule. Nap timers use their own duration.");if(mode==Mode.INTERVAL&&!alarm.days.equals(ALL))throw new IllegalArgumentException("An anchored interval controls all calendar days; weekday filtering cannot be combined with it.");if(mode!=Mode.INTERVAL&&alarm.days.isEmpty())throw new IllegalArgumentException("Choose at least one weekday for odd/even weeks.");}
 boolean validFor(Alarm alarm){try{check(alarm);return true;}catch(IllegalArgumentException invalid){return false;}}
 boolean accepts(LocalDate day){if(mode==Mode.WEEKLY)return true;if(mode==Mode.INTERVAL)return !day.isBefore(anchor)&&ChronoUnit.DAYS.between(anchor,day)%every==0;return day.get(IsoFields.WEEK_OF_WEEK_BASED_YEAR)%2==(mode==Mode.ODD?1:0);}
 long next(Alarm alarm,long now,ZoneId zone){check(alarm);LocalDate day=Instant.ofEpochMilli(now).atZone(zone).toLocalDate();if(mode==Mode.INTERVAL){if(day.isBefore(anchor))day=anchor;else{long remainder=ChronoUnit.DAYS.between(anchor,day)%every;if(remainder!=0)day=day.plusDays(every-remainder);}}try{for(int n=0;n<90;n++){if(day.getYear()>9998)return 0;if(accepts(day)&&(mode==Mode.INTERVAL||alarm.days.contains(day.getDayOfWeek().getValue()))&&day.atStartOfDay(zone).toLocalDate().equals(day)){long at=alarm.solar==null?AlarmDate.at(day,alarm.hour,alarm.minute,zone):alarm.solar.on(day,alarm.hour,alarm.minute,zone).at;if(at>now&&Instant.ofEpochMilli(at).atZone(zone).toLocalDate().equals(day)&&(alarm.skip==null||!alarm.skip.excludes(at,zone)))return at;}day=day.plusDays(mode==Mode.INTERVAL?every:1);}return 0;}catch(DateTimeException unsupported){return 0;}}
 String label(){return switch(mode){case WEEKLY->"Weekly / one-time";case ODD->"Odd ISO weeks";case EVEN->"Even ISO weeks";case INTERVAL->"Every "+every+(every==1?" day":" days")+" · from "+anchor;};}
 String key(){return custom()?"repeat-v1:"+mode+(mode==Mode.INTERVAL?":"+every+":"+anchor:""):"";}
 static String key(Alarm alarm){return alarm.repeatInvalid?":invalid-repeat:"+alarm.json().opt("repeatRule"):alarm.repeatRule.custom()?":"+alarm.repeatRule.key():"";}
 static JSONObject encode(AlarmRepeat rule)throws JSONException{JSONObject row=new JSONObject().put("version",1).put("mode",rule.mode.name());if(rule.mode==Mode.INTERVAL)row.put("every",rule.every).put("anchor",rule.anchor.toString());return row;}
 static AlarmRepeat decode(Object raw)throws JSONException{if(!(raw instanceof JSONObject row)||SensorProvenance.whole(row,"version")!=1)throw new JSONException("Unsupported repeat rule");try{Mode mode=Mode.valueOf(SensorProvenance.text(row,"mode"));if(row.length()!=(mode==Mode.INTERVAL?4:2))throw new JSONException("Unexpected repeat fields");if(mode!=Mode.INTERVAL)return mode==Mode.WEEKLY?WEEKLY:new AlarmRepeat(mode,0,null);long every=SensorProvenance.whole(row,"every");if(every<1||every>365)throw new JSONException("Choose an interval of 1–365 days");return new AlarmRepeat(mode,(int)every,AlarmDate.read(row.get("anchor")));}catch(IllegalArgumentException invalid){throw new JSONException("Invalid repeat rule");}}
 static Set<Integer> days(Object raw)throws JSONException{if(!(raw instanceof JSONArray array)||array.length()>7)throw new JSONException("Choose valid weekdays");Set<Integer> result=new TreeSet<>();for(int n=0;n<array.length();n++){Object value=array.get(n);if(!(value instanceof Integer)||((Integer)value)<1||((Integer)value)>7||!result.add((Integer)value))throw new JSONException("Weekdays must be unique integers from 1 to 7");}return result;}
 static String identity(Alarm alarm){try{byte[] bytes=java.security.MessageDigest.getInstance("SHA-256").digest(alarm.json().toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));StringBuilder value=new StringBuilder();for(byte b:bytes)value.append(String.format(Locale.ROOT,"%02x",b&255));return value.toString();}catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}}
}
